// Actual pinned PNGdec API regression; fixture generated by test_png_workspace_native.py.
#include <PNGdec.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <vector>
static_assert(PNG_EXTERNAL_WORKSPACE_VERSION == 1, "Reviewed workspace patch required");
static void need(bool v, const char* m) {
  if (!v) {
    std::fprintf(stderr, "FAILED %s\n", m);
    std::exit(3);
  }
}
static std::vector<uint8_t> pixels;
static int draw(PNGDRAW* d) {
  need(d->iPixelType == 0 && d->iBpp == 8 && d->iWidth == 160, "original wire type");
  pixels.insert(pixels.end(), d->pPixels, d->pPixels + 160);
  return 1;
}
int main(int argc, char** argv) {
  need(argc == 2, "file argument");
  std::ifstream f(argv[1], std::ios::binary);
  std::vector<uint8_t> input{std::istreambuf_iterator<char>(f), {}};
  need(!input.empty(), "fixture bytes");
  PNG png;
  need(png.openRAM(input.data(), input.size(), draw) == PNG_SUCCESS, "open");
#ifdef PNG_EXTERNAL_WORKSPACE_VERSION
  static_assert(PNG_EXTERNAL_WORKSPACE_VERSION == 1);
  alignas(16) static uint8_t state[PNG_DECODE_STATE_BYTES + 16];
  alignas(16) static uint8_t window[PNG_DECODE_WINDOW_BYTES + 16];
  alignas(16) static uint8_t rows[PNG_MAX_BUFFERED_PIXELS + 16];
  constexpr size_t requiredRows = (160 + 1) * 2 + 32;
  auto bind = [&]() {
    return png.setDecodeWorkspace(state, PNG_DECODE_STATE_BYTES, window, PNG_DECODE_WINDOW_BYTES, rows, requiredRows);
  };
  auto unbound = [&]() {
    pixels.clear();
    need(png.decode(nullptr, 0) == PNG_NO_BUFFER, "unbound decode fails closed");
    need(pixels.empty(), "unbound no callback");
  };
  unbound();
  // Binding must reproduce the old embedded-array initialization without
  // touching unused capacity owned by the caller.
  std::memset(state, 0xa5, sizeof(state));
  std::memset(window, 0xa5, sizeof(window));
  std::memset(rows, 0xa5, sizeof(rows));
  need(bind(), "bind nonzero workspace");
  auto initialized = [](const uint8_t* bytes, size_t used, size_t capacity) {
    return std::all_of(bytes, bytes + used, [](uint8_t b) { return b == 0; }) &&
           std::all_of(bytes + used, bytes + capacity, [](uint8_t b) { return b == 0xa5; });
  };
  need(initialized(state, PNG_DECODE_STATE_BYTES, sizeof(state)), "state zero and canary");
  need(initialized(window, PNG_DECODE_WINDOW_BYTES, sizeof(window)), "window zero and canary");
  need(initialized(rows, requiredRows, sizeof(rows)), "rows zero and canary");
  unsigned rejected = 0;
  auto bad = [&](void* s, size_t sn, uint8_t* w, size_t wn, uint8_t* r, size_t rn) {
    need(bind(), "fresh valid binding before negative");
    need(!png.setDecodeWorkspace(s, sn, w, wn, r, rn), "invalid bind rejected");
    unbound();
    ++rejected;
  };
  bad(nullptr, sizeof(state), window, sizeof(window), rows, sizeof(rows));
  bad(state, PNG_DECODE_STATE_BYTES - 1, window, sizeof(window), rows, sizeof(rows));
  bad(state + 1, PNG_DECODE_STATE_BYTES, window, sizeof(window), rows, sizeof(rows));
  bad(state, sizeof(state), nullptr, sizeof(window), rows, sizeof(rows));
  bad(state, sizeof(state), window, PNG_DECODE_WINDOW_BYTES - 1, rows, sizeof(rows));
  bad(state, sizeof(state), window + 1, PNG_DECODE_WINDOW_BYTES, rows, sizeof(rows));
  bad(state, sizeof(state), window, sizeof(window), nullptr, sizeof(rows));
  bad(state, sizeof(state), window, sizeof(window), rows, requiredRows - 1);
  bad(state, sizeof(state), window, sizeof(window), rows + 1, requiredRows);
  bad(state, sizeof(state), window, sizeof(window), window, requiredRows);
  bad(window, PNG_DECODE_STATE_BYTES, window, PNG_DECODE_WINDOW_BYTES, rows, requiredRows);
  bad(reinterpret_cast<void*>(UINTPTR_MAX & ~uintptr_t(15)), PNG_DECODE_STATE_BYTES, window, sizeof(window), rows,
      requiredRows);
  need(bind(), "valid bind");
  pixels.clear();
  need(png.decode(nullptr, PNG_FAST_PALETTE) == PNG_UNSUPPORTED_FEATURE, "fast palette explicit refusal");
  need(pixels.empty(), "fast palette no callback");
  need(bind(), "rebind after unsupported mode");
#endif
  pixels.clear();
  need(png.decode(nullptr, PNG_CHECK_CRC) == PNG_SUCCESS, "first actual decode");
  need(pixels.size() == 17920, "first pixels");
  for (size_t y = 0; y < 112; ++y)
    for (size_t x = 0; x < 160; ++x)
      need(pixels[y * 160 + x] == uint8_t((x * 17 + y * 29 + (x ^ y) * 3) & 255), "nonuniform pixel oracle");
  auto first = pixels;
  pixels.clear();
  need(png.decode(nullptr, PNG_CHECK_CRC) == PNG_SUCCESS, "repeat same opened image");
  need(pixels == first, "repeat pixels");
  need(png.openRAM(input.data(), input.size(), draw) == PNG_SUCCESS, "reopen");
#ifdef PNG_EXTERNAL_WORKSPACE_VERSION
  unbound();
  need(bind(), "reopen requires binding");
#endif
  pixels.clear();
  need(png.decode(nullptr, PNG_CHECK_CRC) == PNG_SUCCESS && pixels == first, "reopen pixels");
  png.close();
#ifdef PNG_EXTERNAL_WORKSPACE_VERSION
  unbound();
#endif
#ifdef PNG_EXTERNAL_WORKSPACE_VERSION
  std::printf(
      "API version=1 rejected=%u repeat=PASS reopen=PASS stateBytes=%zu windowBytes=%u rowCapacity=%zu sizeofPNG=%zu\n",
      rejected, size_t(PNG_DECODE_STATE_BYTES), unsigned(PNG_DECODE_WINDOW_BYTES), requiredRows, sizeof(PNG));
#else
  std::printf("API golden repeat=PASS reopen=PASS sizeofPNG=%zu\n", sizeof(PNG));
#endif
}
